// seq_detector_sr.sv - composite detector: Z1 = 101 always; Z2 = 011 until it fires, then only Z1 until Z1 fires.
// Generated by scripts/emit_sv.py from scripts/fsms.py - do not edit by hand.
// Flip-flops: SR, logic: minimal POS (exact two-level minimisation with don't-cares),
// next-state 9 two-input gates, outputs 5 two-input gates.
// State encoding:
//   S0     = 000
//   T0/T1  = 111
//   S1     = 011
//   S2     = 001
//   T2/T3  = 100
//   S3     = 101
//   S4     = 010
//   T4     = 110
// 8 states after minimising the 10-state composite machine; encoding chosen by prioritized adjacency
// plus an exhaustive search over all 8! encodings (scripts/explore_detector.py).

module seq_detector_sr (
  input  logic clk,
  input  logic rst,   // synchronous, to S0
  input  logic x,
  output logic z1,
  output logic z2
);
  logic [2:0] q, qn;
  logic r0, r1, r2, s0, s1, s2;
  assign s2     = q[1] & x;  // 1 gates
  assign r2     = q[0] & ~x & qn[1];  // 2 gates
  assign s1     = ~x;  // 0 gates
  assign r1     = x;  // 0 gates
  assign s0     = qn[0] & (qn[2] | q[1]);  // 2 gates
  assign r0     = q[0] & (q[2] | ~x) & (qn[1] | x);  // 4 gates
  assign z1     = q[1] & x & qn[0];  // 2 gates
  assign z2     = q[2] & q[0] & x & qn[1];  // 3 gates

  sr_ff u_q2 (.clk, .s(s2 & ~rst), .r(r2 | rst), .q(q[2]), .qn(qn[2]));
  sr_ff u_q1 (.clk, .s(s1 & ~rst), .r(r1 | rst), .q(q[1]), .qn(qn[1]));
  sr_ff u_q0 (.clk, .s(s0 & ~rst), .r(r0 | rst), .q(q[0]), .qn(qn[0]));
endmodule
